export function knowledgeBaseText() {
  const lines = [
    `Name: ${PROFILE.name}. ${PROFILE.degree}, ${PROFILE.school}, graduating ${PROFILE.graduation}. Contact: ${PROFILE.email}, GitHub @Vaunty, LinkedIn /in/matthewngoy.`,
    "",
  ];
  for (const t of TOPICS) {
    lines.push(`## ${t.title} (${t.id})`);
    for (const f of t.facts) lines.push(`- ${f.replace(/\*\*/g, "")}`);
    lines.push("");
  }
  lines.push("## Timeline");
  for (const e of TIMELINE) lines.push(`- ${e.date}: ${e.title} (${e.org}). ${e.desc}`);
  lines.push("", "## Not known (say you'd rather not guess)",
    "- Exact text of the Beijing speech; hours per week as a volunteer mentor; certifications.",
    "- Anything about family, other students' grades, or unpublished vulnerability details.");
  return lines.join("\n");
}
